    47	 *   Create a directory and all parent directories (like mkdir -p).
    48	 *   Returns 0 on success or if directory already exists.
    49	 ****************************************************************************/
    50	
    51	static int vg_mkdir_p(const char *path)
    52	{
    53	  char tmp[128];
    54	  char *p = NULL;
    55	  size_t len;
    56	
    57	  snprintf(tmp, sizeof(tmp), "%s", path);
    58	  len = strlen(tmp);
    59	
    60	  if (tmp[len - 1] == '/')
    61	    {
    62	      tmp[len - 1] = '\0';
    63	    }
    64	
    65	  for (p = tmp + 1; *p; p++)
    66	    {
    67	      if (*p == '/')
    68	        {
    69	          *p = '\0';
    70	          if (mkdir(tmp, 0755) != 0 && errno != EEXIST)
    71	            {
    72	              return -errno;
    73	            }
    74	
    75	          *p = '/';
    76	        }
    77	    }
    78	
    79	  if (mkdir(tmp, 0755) != 0 && errno != EEXIST)
    80	    {
    81	      return -errno;
    82	    }
    83	
    84	  return 0;
    85	}
